const bruto = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : msg.payload;
let dados;

try {
    dados = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;
} catch (erro) {
    node.warn('Mensagem MQTT ignorada: JSON invalido');
    return null;
}

const camposObrigatorios = ['maquina', 'status', 'pecas_boas', 'pecas_defeituosas'];
const ausentes = camposObrigatorios.filter((campo) => dados[campo] === undefined || dados[campo] === null);
if (ausentes.length > 0) {
    node.warn('Mensagem MQTT ignorada. Campos ausentes: ' + ausentes.join(', '));
    return null;
}

const timestamp = dados.timestamp || new Date().toISOString();
const linha = [timestamp, dados.maquina, dados.status, dados.pecas_boas, dados.pecas_defeituosas, dados.tempo_ciclo_segundos || ''].join(',') + '\n';

msg.payload = linha;
return msg;
